const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

class ParseError extends Error {
  constructor (line, message) {
    super(message)
    this.line = line
  }
}

function fail (line, message) {
  throw new ParseError(line, message)
}

/**
 * Parses the full text of an election. Returns { candidates, ballots }
 * where candidates is an array of names in declaration order and ballots
 * is an array of { count: BigInt, prefs: string[] }.
 *
 * Throws ParseError on any malformed input, with a `line` property set
 * when the failure is tied to a specific input line (undefined otherwise).
 */
export function parseElection (input) {
  const lines = input.split('\n')
  if (input.endsWith('\n')) lines.pop()

  let candidatesDeclared = false
  const candidates = []
  const declared = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 2) {
        fail(lineNo, 'expected candidates <name>...')
      }
      for (const name of tokens.slice(1)) {
        if (!NAME_RE.test(name)) {
          fail(lineNo, `invalid candidate name ${name}`)
        }
        if (declared.has(name)) {
          fail(lineNo, `candidate ${name} is declared twice`)
        }
        declared.add(name)
        candidates.push(name)
      }
      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        fail(lineNo, 'expected ballot <count> <candidate>...')
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr)) {
        fail(lineNo, 'count must be a positive integer')
      }
      const count = BigInt(countStr)
      const prefs = tokens.slice(2)
      const seen = new Set()
      for (const name of prefs) {
        if (!declared.has(name)) {
          fail(lineNo, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          fail(lineNo, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, prefs })
    } else {
      fail(lineNo, `unknown directive ${directive}`)
    }
  }

  if (!candidatesDeclared) {
    fail(undefined, 'no candidates')
  }

  return { candidates, ballots }
