 * Instant-runoff counting logic.
 */

/**
 * Runs the election, returning an array of round results and the winner
 * (or null when nobody wins).
 *
 * Each round result is:
 *   { votes: Map<name, BigInt>, exhausted: BigInt, eliminated: string|null }
 * `votes` holds an entry for every candidate continuing at the start of
 * that round. `eliminated` names the candidate removed after this round,
 * or null when the round ended the election (winner or no winner).
 */
export function runElection (candidates, ballots) {
  let continuing = new Set(candidates)
  const roundHistory = [] // array of Map<name, BigInt>, one per round
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0n)
    let exhausted = 0n

    for (const ballot of ballots) {
      const choice = ballot.prefs.find((c) => continuing.has(c))
      if (choice !== undefined) {
        votes.set(choice, votes.get(choice) + ballot.count)
      } else {
        exhausted += ballot.count
      }
    }

    roundHistory.push(votes)

    let activeTotal = 0n
    for (const v of votes.values()) activeTotal += v

    if (activeTotal === 0n) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = null
      break
    }

    let majorityWinner = null
    for (const [name, v] of votes) {
      if (v * 2n > activeTotal) {
        majorityWinner = name
        break
      }
    }

    if (majorityWinner !== null) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = majorityWinner
      break
    }

    let minVotes = null
    for (const v of votes.values()) {
      if (minVotes === null || v < minVotes) minVotes = v
    }
    const tied = [...votes.keys()].filter((name) => votes.get(name) === minVotes)

    const eliminated = tied.length === 1 ? tied[0] : pickEliminated(roundHistory, tied)
    rounds.push({ votes, exhausted, eliminated })
    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
}

function pickEliminated (roundHistory, tiedNames) {
  let group = tiedNames
  for (;;) {
    let shrunk = false
    for (const votes of roundHistory) {
      let min = null
      for (const name of group) {
        const v = votes.get(name)
        if (min === null || v < min) min = v
      }
      if (group.some((name) => votes.get(name) !== min)) {
        group = group.filter((name) => votes.get(name) === min)
        shrunk = true
        break
      }
    }
    if (!shrunk) break
    if (group.length === 1) break
  }
  group = [...group].sort()
  return group[group.length - 1]
}
"}

