{"file_path":"src/format.js","content":"/**
 * Rendering of election results as the two CLI modes' output.
 */

function formatRoundLine (roundNumber, votes, exhausted) {
  const entries = [...votes.entries()].sort((a, b) => {
    if (a[1] !== b[1]) return a[1] > b[1] ? -1 : 1
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, v]) => `${name}=${v}`)
  parts.push(`exhausted=${exhausted}`)
  return `round ${roundNumber}: ${parts.join(' ')}`
}

function winnerLine (winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}

export function formatRounds (result) {
  const lines = []
  result.rounds.forEach((round, i) => {
    lines.push(formatRoundLine(i + 1, round.votes, round.exhausted))
    if (round.eliminated !== null) {
      lines.push(`eliminated ${round.eliminated}`)
    }
  })
  lines.push(winnerLine(result.winner))
  return lines.join('\n') + '\n'
}

export function formatTally (result) {
  const lines = []
  lines.push(`rounds ${result.rounds.length}`)
  lines.push(winnerLine(result.winner))
  return lines.join('\n') + '\n'
}
"}

